content.applied_patch:
--- a/rtl/sequence.sv
+++ b/rtl/sequence.sv
@@ -1,4 +1,3 @@
-
 module TopModule(
    input   clk,
    input   rst_n,
@@ -9,27 +8,38 @@
 reg  [3:0] bin_out;
 wire [3:0] gray_wire;

+reg [1:0] cycle_count;
+
 always @(posedge clk or negedge rst_n)begin
    if(rst_n == 1'b0) begin
       bin_out <= 4'b0;
+      cycle_count <= 2'b0;
    end
    else begin
       bin_out[3] = gray_wire[3];
       bin_out[2] = gray_wire[2]^bin_out[3];
       bin_out[1] = gray_wire[1]^bin_out[2];
-      bin_out[0] = gray_wire[0]&bin_out[1];
+      bin_out[0] = gray_wire[0]^bin_out[1];
+      
+      if (cycle_count == 2'b01) begin
+         cycle_count <= 2'b0;
+      end else begin
+         cycle_count <= cycle_count + 1'b1;
+      end
    end 
 end
+
 //Binary increment
 reg [3:0] bin_add_wire;
 always @(posedge clk or negedge rst_n)begin
    if(rst_n == 1'b0) begin
       bin_add_wire <= 4'b0;
    end
-   else begin
+   else if (cycle_count == 2'b00) begin
       bin_add_wire <= bin_out + 1'b1;
    end
 end
+
 //Binary to gray code conversion
 assign gray_wire = (bin_add_wire >> 1) ^ bin_add_wire;

